#!/usr/bin/env bash
# Cursor beforeReadFile + beforeShellExecution hook
# (harness/cursor/tea-rags/scripts/deny-indexed-read.sh, generated by
# scripts/gen-harness-cursor.ts; bd tea-rags-mcp-xkbkv): the Cursor form of the
# Claude plugin's deny-indexed-read.sh. It asks
# `tea-rags project indexed --path | --command --cwd --json` and answers
# {"permission":"deny", user_message, agent_message} when the file is indexed.
# Every other outcome is {"permission":"allow"} with exit 0: Cursor blocks a
# permission hook whose stdout is not schema-valid JSON, so failing open means
# printing allow, never printing nothing.
set -u
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$ROOT/harness/cursor/tea-rags/scripts/deny-indexed-read.sh"
PASS=0; FAIL=0
note() { if [ "$1" = 0 ]; then PASS=$((PASS+1)); echo "ok   - $2"; else FAIL=$((FAIL+1)); echo "FAIL - $2"; fi; }

# Fake `tea-rags` on PATH: `project indexed <args…>` records each arg on its own
# line, prints $FAKE_OUT, exits $FAKE_EXIT.
FAKEBIN="$(mktemp -d)"; CALLS="$(mktemp)"; SCRATCH="$(mktemp -d)"
cat > "$FAKEBIN/tea-rags" <<'EOF'
#!/usr/bin/env bash
[ "$1 $2" = "project indexed" ] || exit 3
shift 2
for a in "$@"; do printf '%s\n' "$a" >> "$CALLS"; done
printf '%s\n' "$FAKE_OUT"
exit "$FAKE_EXIT"
EOF
chmod +x "$FAKEBIN/tea-rags"
# A PATH holding jq and the base system but no tea-rags (the CLI-missing case).
NOCLI="$(mktemp -d)"; ln -s "$(command -v jq)" "$NOCLI/jq"
BASE_PATH="/usr/bin:/bin"
export CALLS

run() { # $1=json payload, $2=fake stdout, $3=fake exit, [$4=PATH]
  : > "$CALLS"; export FAKE_OUT="$2" FAKE_EXIT="$3"
  OUT=$(printf '%s' "$1" | env -u TEA_RAGS_BIN HOME="$SCRATCH" CURSOR_PROJECT_DIR=/repo PATH="${4:-$FAKEBIN:$NOCLI:$BASE_PATH}" bash "$HOOK" 2>/dev/null)
  CODE=$?
}
read_of() { jq -cn --arg f "$1" '{hook_event_name:"beforeReadFile",file_path:$f,content:"x",attachments:[],tool_use_id:"t1",workspace_roots:["/repo"]}'; }
shell_of() { jq -cn --arg c "$1" '{hook_event_name:"beforeShellExecution",command:$c,cwd:"/repo/sub",sandbox:false,tool_use_id:"t2",workspace_roots:["/repo"]}'; }
asked() { grep -qxF -- "$1" "$CALLS"; }
perm() { printf '%s' "$OUT" | jq -r '.permission // empty' 2>/dev/null; }
allowed() { [ "$CODE" = 0 ] && [ "$(perm)" = allow ]; }
denied() { # $1=substring of the reason, checked in both user_message and agent_message
  [ "$CODE" = 0 ] && [ "$(perm)" = deny ] \
    && printf '%s' "$OUT" | jq -r '.user_message' | grep -qF -- "$1" \
    && printf '%s' "$OUT" | jq -r '.agent_message' | grep -qF -- "$1"
}

INDEXED='{"indexed":true,"project":"repo","collectionName":"code_repo","relativePath":"src/a.ts"}'

[ -f "$HOOK" ]
note $? "hook script is generated"

# --- beforeReadFile ---
run "$(read_of /repo/src/a.ts)" "$INDEXED" 0
denied 'find_symbol(relativePath: "src/a.ts")'; note $? "read of an indexed file is denied with find_symbol"
denied 'find_symbol(symbols: [<the method ids you need>])'; note $? "deny reason offers find_symbol(symbols) for known ids"
denied 'File reads are for files outside the index.'; note $? "read deny reason says what file reads are for"
{ asked --path && asked /repo/src/a.ts && asked --json; }; note $? "the CLI gets --path <file> --json"

run "$(read_of src/a.ts)" "$INDEXED" 0
asked /repo/src/a.ts; note $? "a relative file_path resolves against CURSOR_PROJECT_DIR"

run "$(read_of /repo/package.json)" '{"indexed":false}' 1
allowed; note $? "read of a non-indexed file is allowed"

run "$(read_of /repo/logo.PNG)" "$INDEXED" 0
{ allowed && [ ! -s "$CALLS" ]; }; note $? "media files skip the CLI"

run "$(jq -cn '{hook_event_name:"beforeReadFile",file_path:"/repo/src/a.ts",attachments:[{type:"file",file_path:"/repo/src/a.ts"}]}')" "$INDEXED" 0
{ allowed && [ ! -s "$CALLS" ]; }; note $? "a user attachment is never denied"

run "$(read_of /repo/src/a.ts)" "$INDEXED" 0 "$NOCLI:$BASE_PATH"
allowed; note $? "missing tea-rags CLI fails open on read"

# --- beforeShellExecution ---
run "$(shell_of 'sed -n 1,80p src/a.ts')" "$INDEXED" 0
denied 'find_symbol(relativePath: "src/a.ts")'; note $? "sed -n of an indexed file is denied"
denied 'Shell file reads are for files outside the index.'; note $? "shell deny reason says what shell reads are for"
{ asked --command && asked 'sed -n 1,80p src/a.ts' && asked --cwd && asked /repo/sub; }; note $? "the CLI gets the command and the hook cwd"

run "$(shell_of 'cat a.rb && head -40 src/a.ts')" "$INDEXED" 0
{ denied 'src/a.ts' && [ "$(grep -cxF -- --command "$CALLS")" = 1 ]; }; note $? "compound read is denied in one CLI call"

run "$(shell_of 'git diff | head -50')" '{"indexed":false}' 1
allowed; note $? "git diff | head is allowed"

run "$(shell_of 'npm test && git status')" "$INDEXED" 0
{ allowed && [ ! -s "$CALLS" ]; }; note $? "command without a reader skips the CLI"

run "$(jq -cn '{hook_event_name:"beforeShellExecution",command:"cat src/a.ts",cwd:""}')" "$INDEXED" 0
asked /repo; note $? "an empty cwd falls back to CURSOR_PROJECT_DIR"

run "$(shell_of 'sed -n 1,80p src/a.ts')" "$INDEXED" 0 "$NOCLI:$BASE_PATH"
allowed; note $? "missing tea-rags CLI fails open on shell"

run "$(shell_of 'sed -n 1,80p src/a.ts')" "garbage" 2
allowed; note $? "CLI error exit fails open"

run "$(shell_of 'sed -n 1,80p src/a.ts')" "not json" 0
allowed; note $? "unparsable CLI output fails open"

# --- input it does not own ---
run 'not json' "$INDEXED" 0
allowed; note $? "malformed hook input fails open"

run '{"hook_event_name":"preToolUse"}' "$INDEXED" 0
{ allowed && [ ! -s "$CALLS" ]; }; note $? "another event is allowed untouched"

rm -rf "$FAKEBIN" "$NOCLI" "$CALLS" "$SCRATCH"
echo "# $PASS passed, $FAIL failed"
[ "$FAIL" = 0 ]
